// shader-skin.js
/* global pc */
var ShaderSkin = pc.createScript('shaderSkin');
ShaderSkin.attributes.add('preset', {type:'string', default:'gold', enum:[{Gold:'gold'},{Lava:'lava'},{Celestial:'celestial'},{Rubber:'rubber'},{Bulge:'bulge'},{Water:'water'},{Chrome:'chrome'},{Bubblegum:'gum'},{Glitch:'glitch'},{Rainbow:'rainbow'},{'Arctic Core':'arctic'},{'Toxic Reactor':'toxic'},{'Infernal Obsidian':'obsidian'},{'Holographic Foil':'foil'},{'Solar Flare':'solar'},{'Cyber Circuit':'circuit'},{'Candy Swirl':'candy'},{'Royal Marble':'marble'},{'Void Eclipse':'void'}]});
ShaderSkin.attributes.add('bendAxis',{type:'string',default:'z',enum:[{X:'x'},{Y:'y'},{Z:'z'}]});
ShaderSkin.attributes.add('speed', {type:'number',default:1,min:0,max:4});
ShaderSkin.attributes.add('strength', {type:'number',default:0.65,min:0,max:1});
ShaderSkin.attributes.add('patternScale', {type:'number',default:1,min:0.1,max:8});
ShaderSkin.attributes.add('includeChildren', {type:'boolean',default:true});
// Bend Axis selects the deformation axis. Supports rigid and skinned render meshes; morphs skipped.
ShaderSkin.prototype.initialize = function () {
    this.time=0; this.last=this.entity.getPosition().clone(); this.motion=new pc.Vec3();
    this.inverse=new pc.Mat4(); this.velocity=new pc.Vec3(); this.localVelocity=new pc.Vec3();
    this.bound=[]; this.material=null;this.rootInv=new pc.Mat4();this.motionData=new Float32Array(3);
    this.on('enable',this.apply,this); this.on('disable',this.restore,this);
    this.on('destroy',function(){this.restore(); if(this.material)this.material.destroy();},this);
    this.on('attr:preset',function(){if(this.enabled)this.apply();},this);
    this.on('attr:includeChildren',function(){if(this.enabled)this.apply();},this);
    this.apply();
};
ShaderSkin.prototype.restore=function(){
    this.bound.forEach(function(b){if(b.mi.material===this.material)b.mi.material=b.material;b.mi.cull=b.cull;},this);
    this.bound=[];
};
ShaderSkin.prototype.apply=function(){
    this.restore(); if(this.material)this.material.destroy();
    this.material=ShaderSkin.makeMaterial(this.app.graphicsDevice,this.preset);
    var renders=this.includeChildren?this.entity.findComponents('render'):[this.entity.render];
    renders.forEach(function(r){if(!r)return;r.meshInstances.forEach(function(mi){
        if(mi.morphInstance){console.warn('shaderSkin: morph mesh skipped.');return;}
        this.bound.push({mi:mi,material:mi.material,cull:mi.cull});mi.material=this.material;
        // Deformed vertices can leave the original AABB. Disable frustum culling on these only.
        if(['rubber','bulge','glitch'].indexOf(this.preset)!==-1)mi.cull=false;
    },this);},this);
    var bounds=null,inv=this.entity.getWorldTransform().clone().invert();
    this.bound.forEach(function(b){var transform=new pc.Mat4().mul2(inv,b.mi.node.getWorldTransform());var box=new pc.BoundingBox();box.setFromTransformedAabb(b.mi.mesh.aabb,transform);if(bounds)bounds.add(box);else bounds=box;});
    var c=bounds?bounds.center:new pc.Vec3(),h=bounds?bounds.halfExtents:new pc.Vec3(0.5,0.5,0.5);
    this.material.setParameter('uCenter',[c.x,c.y,c.z]);this.material.setParameter('uSize',Math.max(h.x,h.y,h.z)*2||1);
    this.material.setParameter('uRootInverse',inv.data);this.material.setParameter('uRootWorld',this.entity.getWorldTransform().data);this.material.setParameter('uAxis',this.bendAxis==='x'?0:this.bendAxis==='y'?1:2);
    this.material.setParameter('uTime',this.time);
    this.material.setParameter('uStrength',this.strength);
    this.material.setParameter('uScale',this.patternScale);
    this.material.setParameter('uMotion',[0,0,0]);
};
ShaderSkin.prototype.update=function(dt){
    this.time+=Math.min(dt,0.05)*this.speed;this.rootInv.copy(this.entity.getWorldTransform()).invert();
    this.material.setParameter('uRootInverse',this.rootInv.data);this.material.setParameter('uRootWorld',this.entity.getWorldTransform().data);this.material.setParameter('uAxis',this.bendAxis==='x'?0:this.bendAxis==='y'?1:2);
    var pos=this.entity.getPosition(); this.velocity.sub2(pos,this.last).mulScalar(1/Math.max(dt,0.001));this.last.copy(pos);
    this.inverse.copy(this.entity.getWorldTransform()).invert();this.inverse.transformVector(this.velocity,this.localVelocity);
    this.localVelocity.mulScalar(-0.12);this.localVelocity.x=pc.math.clamp(this.localVelocity.x,-0.6,0.6);this.localVelocity.z=pc.math.clamp(this.localVelocity.z,-0.6,0.6);
    this.motion.lerp(this.motion,this.localVelocity,1-Math.exp(-dt*7));
    this.material.setParameter('uTime',this.time);this.material.setParameter('uStrength',this.strength);
    this.material.setParameter('uScale',Math.max(0.1,this.patternScale));
    this.motionData[0]=this.motion.x;this.motionData[2]=this.motion.z;this.material.setParameter('uMotion',this.motionData);
};
ShaderSkin.makeMaterial=function(device,preset){
    var deform={
        rubber:'float h=clamp(p.y+0.5,0.0,1.5); p.xz+=uMotion.xz*h*h*uStrength; p.x+=sin(p.y*4.0+uTime*4.0)*0.045*h*uStrength;',
        bulge:'float wave=sin(p.y*7.0-uTime*3.5); p.xz*=1.0+wave*0.28*uStrength;',
        glitch:'float tick=floor(uTime*9.0); float gate=step(0.82,hash(vec2(tick,3.0))); p.x+=gate*(hash(vec2(floor(p.y*9.0),tick))-0.5)*0.32*uStrength;'
    };
    var hash='float hash(vec2 p){vec3 q=fract(vec3(p.xyx)*0.1031);q+=dot(q,q.yzx+33.33);return fract((q.x+q.y)*q.z);}';
    var vertex=['attribute vec3 aPosition;attribute vec3 aNormal;uniform mat4 matrix_model;uniform mat4 matrix_viewProjection;uniform mat3 matrix_normal;',
        'uniform float uTime;uniform float uStrength;uniform vec3 uMotion;uniform mat4 uRootInverse;uniform mat4 uRootWorld;uniform vec3 uCenter;uniform float uSize;uniform float uAxis;',
        'varying vec3 vP;varying vec3 vWorld;varying vec3 vNormal;', '#ifdef SKIN\n#include "skinVS"\n#endif',hash,
        'void main(){vec3 raw=aPosition;vec3 norm=aNormal;\n#ifdef SKIN\nmat4 skin=getSkinMatrix(vertex_boneIndices,vertex_boneWeights);raw=(skin*vec4(raw,1.0)).xyz;norm=mat3(skin)*norm;\n#endif',
        'vec3 root=(uRootInverse*matrix_model*vec4(raw,1.0)).xyz;vec3 p=(root-uCenter)/uSize;vP=p;',
        'if(uAxis<0.5)p=p.yxz;else if(uAxis>1.5)p=p.xzy;',deform[preset]||'',
        'if(uAxis<0.5)p=p.yxz;else if(uAxis>1.5)p=p.xzy;',
        'vWorld=(uRootWorld*vec4(p*uSize+uCenter,1.0)).xyz;vNormal=matrix_normal*norm;gl_Position=matrix_viewProjection*vec4(vWorld,1.0);}'].join('\n');
    var effects={
        arctic: `vec3 q=p*23.0;
float fissure=abs(sin(q.z+sin(q.y*0.8)*1.8)+sin(q.x*0.7-q.y*1.3));
float edge=1.0-smoothstep(0.035,0.20,fissure);
float frost=0.5+0.5*sin(p.z*9.0+p.y*7.0);
color=mix(vec3(0.015,0.08,0.27),vec3(0.08,0.36,0.66),frost)*(0.65+0.35*light);
color+=edge*vec3(0.08,0.7,0.9);
float runner=pow(max(0.0,sin(p.z*13.0-uTime*2.0)),12.0);
color+=edge*runner*vec3(0.8,0.95,1.0)+spec*0.65+rim*vec3(0.1,0.32,0.45);`,
        toxic: `float flow=sin(p.z*25.0+sin(p.y*23.0+uTime*0.55)*1.3)+sin(p.x*18.0-p.y*20.0);
float vein=1.0-smoothstep(0.15,0.45,abs(flow));
float pulse=pow(max(0.0,sin(p.z*17.0-uTime*3.0)),8.0);
color=vec3(0.045,0.065,0.027)*(0.7+0.3*light);
color+=vein*mix(vec3(0.18,0.85,0.005),vec3(1.0,0.95,0.04),pulse);
color+=spec*0.2+rim*vec3(0.03,0.2,0.0);`,
        obsidian: `vec3 q=p*13.0;
float seam=min(abs(fract(q.z+q.y*0.7)-0.5),abs(fract(q.y-q.x*0.65+q.z*0.23)-0.5));
float aa=max(fwidth(seam),0.006);
float crack=1.0-smoothstep(0.014,0.025+aa,seam);
float facet=hash(floor(vec2(q.z+q.y*0.7,q.y-q.x*0.65+q.z*0.23)));
color=mix(vec3(0.025,0.012,0.045),vec3(0.14,0.065,0.22),facet)*(0.7+0.3*light);
float flare=pow(max(0.0,sin(uTime*1.7+facet*21.0)),24.0);
color+=crack*mix(vec3(0.85,0.01,0.5),vec3(1.0,0.8,1.0),flare)+spec*0.7+rim*vec3(0.12,0.04,0.2);`,
        foil: `float angle=dot(n,v);
float phase=angle*1.6+r.x*0.35+p.z*0.8+uTime*0.09;
vec3 spectrum=0.5+0.5*cos(6.28318*(phase+vec3(0.0,0.33,0.67)));
color=mix(vec3(0.27,0.24,0.36),spectrum,0.85)*(0.65+0.35*light);
float emboss=0.5+0.5*sin((p.z+p.y)*95.0);
color+=spectrum*emboss*0.13+spec*0.8+rim*vec3(0.25,0.22,0.3);`,
        solar: `float swirl=sin(p.z*27.0+sin(p.y*18.0+uTime*0.8)*2.4+sin(p.x*15.0-uTime*0.5));
float grain=0.5+0.5*sin(p.y*44.0+swirl*3.0-uTime*1.4);
color=mix(vec3(0.55,0.025,0.004),vec3(1.0,0.38,0.012),0.5+0.5*swirl);
float eruption=smoothstep(0.72,0.98,grain)*smoothstep(0.0,0.75,swirl);
color=mix(color,vec3(1.0,0.88,0.16),eruption);
color*=0.78+0.22*light;color+=rim*vec3(0.3,0.08,0.0);`,
        circuit: `vec2 q=vec2(p.z,p.y+p.x*0.32)*15.0;
vec2 cell=floor(q),f=fract(q);float seed=hash(cell);
float lane=mix(0.25,0.75,step(0.5,seed));
float route=min(abs(f.y-lane),abs(f.x-0.5));
float aa=max(fwidth(route),0.008);
float trace=1.0-smoothstep(0.022,0.035+aa,route);
float pad=1.0-smoothstep(0.045,0.09,length(f-vec2(0.5,lane)));
float pulse=pow(max(0.0,sin(q.x*0.7+q.y*0.25-uTime*3.5)),16.0);
color=vec3(0.025,0.055,0.12)*(0.65+0.35*light);
color+=max(trace,pad)*mix(vec3(0.015,0.38,0.48),vec3(0.4,1.0,0.95),pulse);
color+=spec*0.25+rim*vec3(0.02,0.08,0.14);`,
        candy: `float stripe=sin(p.z*35.0+p.y*23.0+p.x*16.0+sin(p.z*8.0)*1.2-uTime*1.2);
float aa=max(fwidth(stripe),0.015);
float mask=smoothstep(-aa,aa,stripe);
color=mix(vec3(0.85,0.018,0.07),vec3(0.97,0.91,0.82),mask)*(0.65+0.35*light);
color+=spec*0.8+rim*vec3(0.13,0.05,0.07);`,
        marble: `float vein=abs(sin(p.z*20.0+p.y*13.0+sin(p.y*21.0+p.x*14.0)*1.4+sin(p.z*11.0)*0.65));
float gold=1.0-smoothstep(0.035,0.14,vein);
float smoke=1.0-smoothstep(0.12,0.45,vein);
color=mix(vec3(0.91,0.85,0.72),vec3(0.55,0.54,0.52),smoke*0.35)*(0.72+0.28*light);
float sheen=0.5+0.5*sin(r.y*10.0+p.z*8.0-uTime*0.7);
color=mix(color,mix(vec3(0.42,0.22,0.015),vec3(1.0,0.77,0.19),sheen),gold);
color+=spec*0.5+rim*0.1;`,
        void: `float cloud=0.5+0.5*sin(p.z*12.0+sin(p.y*15.0-uTime*0.5)*1.8+sin(p.x*9.0+uTime*0.25));
color=mix(vec3(0.026,0.012,0.06),vec3(0.32,0.055,0.48),cloud*cloud);
float thread=abs(sin(p.y*33.0+p.z*18.0+sin(p.z*24.0+uTime)*0.8));
float gate=pow(max(0.0,sin(p.z*7.0-uTime*2.0)),18.0);
color+=(1.0-smoothstep(0.025,0.12,thread))*gate*vec3(0.15,0.45,1.0);
color+=rim*vec3(0.17,0.035,0.3)+spec*0.16;`,
        gold:'float bands=sin(r.y*13.0+r.x*3.0+uTime*0.65);color=mix(vec3(0.24,0.07,0.005),vec3(1.0,0.63,0.035),smoothstep(-0.5,0.5,bands));color+=vec3(1.0,0.87,0.4)*pow(max(bands,0.0),18.0)*0.9; color+=vec3(1.0,0.62,0.03)*rim*0.7;',
        lava:'vec3 q=p*19.0;float veins=abs(sin(q.x+sin(q.y+uTime)*1.4)+sin(q.z-q.y*0.7+uTime*0.6));float crack=1.0-smoothstep(0.08,0.34,veins);color=mix(vec3(0.11,0.025,0.022),vec3(1.0,0.12,0.005),crack);color+=vec3(1.0,0.68,0.04)*(1.0-smoothstep(0.01,0.12,veins));color+=rim*vec3(0.4,0.025,0.0);',
        celestial:'float neb=0.5+0.5*sin(p.x*5.0+p.y*3.0+sin(p.z*6.0+uTime*0.3)*2.0);color=mix(vec3(0.025,0.04,0.19),vec3(0.4,0.055,0.7),neb);vec2 st=uv*28.0;vec2 cell=floor(st);vec2 f=fract(st)-0.5;float seed=hash(cell);float star=(1.0-smoothstep(0.025,0.1,length(f)))*step(0.5,seed);float crossStar=(1.0-smoothstep(0.012,0.035,min(abs(f.x),abs(f.y))))*(1.0-smoothstep(0.06,0.24,max(abs(f.x),abs(f.y))))*step(0.93,seed);color+=(star+crossStar)*vec3(0.65,0.88,1.0)*(0.65+0.35*sin(uTime*2.0+seed*30.0));color+=rim*vec3(0.12,0.3,0.7);',
        rubber:'color=mix(vec3(0.08,0.12,0.65),vec3(0.25,0.65,1.0),0.5+0.5*sin(p.y*8.0));color*=0.5+0.5*light; color+=spec*0.25+rim*vec3(0.1,0.3,0.7);',
        bulge:'color=mix(vec3(0.22,0.03,0.55),vec3(0.65,0.95,0.05),0.5+0.5*sin(p.y*7.0-uTime*3.5));color*=0.55+0.45*light;color+=spec*0.55;',
        water:'float wave=sin(p.x*12.0+uTime*1.8+sin(p.y*8.0-uTime))+sin(p.z*13.0-uTime*1.3);float caustic=pow(1.0-abs(sin(wave*2.0+p.y*9.0)),10.0);color=mix(vec3(0.015,0.12,0.42),vec3(0.015,0.65,0.85),0.5+0.25*wave);color+=caustic*vec3(0.32,0.75,0.8)*0.7+rim*vec3(0.08,0.5,0.65)+spec*0.6;',
        chrome:'float horizon=smoothstep(-0.07,0.08,r.y);color=mix(vec3(0.025,0.035,0.08),vec3(0.7,0.83,0.95),horizon);color*=0.6+0.4*sin(r.y*16.0+r.x*3.0);color+=pow(max(0.0,sin(r.x*8.0+r.y*5.0)),24.0)*0.7;color+=rim*0.25;',
        gum:'color=mix(vec3(0.58,0.015,0.17),vec3(1.0,0.2,0.57),0.45+0.55*light);float swirl=0.5+0.5*sin(p.y*8.0+p.x*5.0+sin(p.z*7.0+uTime*0.4));color=mix(color,vec3(1.0,0.52,0.78),smoothstep(0.82,0.99,swirl)*0.5);color+=spec*vec3(1.0,0.85,0.95)*0.8+rim*vec3(0.3,0.04,0.15);',
        glitch:'float row=floor(uv.y*28.0);float tick=floor(uTime*8.0);float rnd=hash(vec2(row,tick));float bars=step(0.65,rnd);color=mix(vec3(0.025,0.01,0.09),mix(vec3(0.0,1.0,0.9),vec3(1.0,0.015,0.5),step(0.5,hash(vec2(row+4.0,tick)))),bars);color*=0.6+0.4*step(0.16,fract(uv.y*90.0));color+=rim*vec3(0.28,0.03,0.5);',
        rainbow:'color=0.5+0.5*cos(6.28318*(p.y*0.65+p.x*0.3-uTime*0.2+vec3(0.0,0.333,0.667)));color*=0.6+0.4*light;color+=spec*0.45+rim*0.15;'
    };
    var normal=deform[preset]?'normalize(cross(dFdx(vWorld),dFdy(vWorld)))':'normalize(vNormal)';
    var fragment=['varying vec3 vP;varying vec3 vWorld;varying vec3 vNormal;',
        'uniform vec3 view_position;uniform float uTime;uniform float uScale;',hash,
        'void main(){vec3 p=vP*uScale;vec3 n='+normal+';vec3 v=normalize(view_position-vWorld);vec3 r=reflect(-v,n);',
        'float rim=pow(1.0-max(dot(n,v),0.0),3.0);float light=max(dot(n,normalize(vec3(-0.4,0.8,1.0))),0.0);float spec=pow(max(dot(n,normalize(v+normalize(vec3(-0.4,0.8,1.0)))),0.0),48.0);',
        // Dominant local face projection avoids needing UVs. Seams are intentional in v1.
        'vec3 an=abs(vNormal);vec2 uv=p.xy;if(an.x>an.y&&an.x>an.z)uv=p.zy;else if(an.y>an.z)uv=p.xz;vec3 color;',effects[preset]||effects.gold,
        'gl_FragColor=vec4(clamp(color,0.0,1.0),1.0);}'].join('\n');
    var material=new pc.ShaderMaterial({uniqueName:'ShaderSkin_v1_'+preset,attributes:{aPosition:pc.SEMANTIC_POSITION,aNormal:pc.SEMANTIC_NORMAL},vertexGLSL:vertex,fragmentGLSL:fragment});
    material.blendType=pc.BLEND_NONE;material.cull=pc.CULLFACE_BACK;material.depthWrite=true;material.update();return material;
};


// toon-water.js
/* global pc */
// Static horizontal water: vertex waves + automatic, startup-baked shoreline.
var ToonWater = pc.createScript('toonWater');
ToonWater.attributes.add('waterColor', {type:'rgb', default:[25/255,138/255,197/255]});
ToonWater.attributes.add('shallowColor', {type:'rgb', default:[34/255,170/255,205/255]});
ToonWater.attributes.add('highlightColor', {type:'rgb', default:[0.86,0.98,0.94], title:'Foam color'});
ToonWater.attributes.add('tileSize', {type:'number', default:12, min:0.1, title:'Wave length (world units)'});
ToonWater.attributes.add('flowSpeed', {type:'number', default:1, min:0, title:'Wave speed'});
ToonWater.attributes.add('waveHeight', {type:'number', default:0.18, min:0});
ToonWater.attributes.add('shoreFoam', {type:'boolean', default:true});
ToonWater.attributes.add('shoreWidth', {type:'number', default:2, min:0.1, title:'Shore foam width (world units)'});
ToonWater.attributes.add('shoreResolution', {type:'number', default:256, enum:[{'128':128},{'256':256},{'512':512}]});

// Optional terrain-only root for games with custom character controllers.
ToonWater.attributes.add('shoreRoot', {type:'entity', title:'Shore terrain root (optional)'});

ToonWater.prototype.initialize = function () {
    this.time=0; this.original=[]; this.generated=[];
    this.material = new pc.ShaderMaterial({
        uniqueName:'ToonWater_Static_Shore_v5',
        attributes:{aPosition:pc.SEMANTIC_POSITION},
        vertexGLSL:[
            'attribute vec3 aPosition; uniform mat4 matrix_model; uniform mat4 matrix_viewProjection;',
            'uniform float uTime; uniform float uFrequency; uniform float uHeight;',
            'varying vec3 vWorld; varying vec2 vWave;',
            'void main(){',
            'vec4 w=matrix_model*vec4(aPosition,1.0);',
            'float a=dot(w.xz,vec2(0.94,0.34))*uFrequency-uTime;',
            'float b=dot(w.xz,vec2(-0.38,0.92))*uFrequency*1.6-uTime*2.0;',
            'float h=sin(a)*0.70+sin(b)*0.30;',
            'vWave=vec2(h,cos(a)*0.7+cos(b)*0.3);',
            'w.y+=h*uHeight; vWorld=w.xyz; gl_Position=matrix_viewProjection*w;',
            '}'
        ].join('\n'),
        fragmentGLSL:[
            'uniform sampler2D uShore; uniform vec4 uMap; uniform float uShoreRange;',
            'uniform vec3 uWater; uniform vec3 uShallow; uniform vec3 uFoam;',
            'uniform float uTime; uniform float uFrequency; uniform float uWidth;',
            'varying vec3 vWorld; varying vec2 vWave;',
            'void main(){',
            'vec2 uv=(vWorld.xz-uMap.xy)*uMap.zw;',
            'float inside=step(0.0,uv.x)*step(0.0,uv.y)*step(uv.x,1.0)*step(uv.y,1.0);',
            'float d=mix(uShoreRange,texture2D(uShore,uv).r*uShoreRange,inside);',
            'float nearShore=1.0-smoothstep(0.0,uWidth*4.0,d);',
            'vec3 col=mix(uWater,uShallow,nearShore*0.86);',
            'col*=0.94+0.08*vWave.x+0.06*vWave.y;',
            // Keep the shoreline wash phase; surface crest highlights are intentionally omitted.
            'float q=dot(vWorld.xz,vec2(-0.38,0.92))*uFrequency*1.6-uTime*2.0;',
            'float crossing=sin(q);',
            // A thin contact rim plus an advancing/dissolving band, confined to the coastline.
            'float wash=0.5+0.5*sin(d/uWidth*5.5-uTime*2.0+crossing*0.45);',
            'float rim=1.0-smoothstep(uWidth*0.08,uWidth*0.28,d);',
            'float band=smoothstep(0.65,0.90,wash)*(1.0-smoothstep(uWidth*0.3,uWidth*1.5,d));',
            'float foam=max(rim*0.9,band*0.85);',
            'col=mix(col,uFoam,foam); gl_FragColor=vec4(col,1.0);',
            '}'
        ].join('\n')
    });
    this.material.blendType=pc.BLEND_NONE;
    this.material.depthWrite=true; this.material.depthTest=true;
    this.material.cull=pc.CULLFACE_BACK; this.material.update();
    this.on('enable',this.startLoadingWatch,this);
    this.on('disable',function(){this.stopLoadingWatch();this.restore();},this);
    this.on('destroy',function(){
        this.stopLoadingWatch(); this.restore(); this.material.destroy();
        if(this.shoreTexture)this.shoreTexture.destroy();
        this.generated.forEach(function(m){m.destroy();});
    },this);
    ['waterColor','shallowColor','highlightColor','tileSize','waveHeight'].forEach(function(a){this.on('attr:'+a,this.parameters,this);},this);
    ['shoreFoam','shoreWidth','shoreResolution','shoreRoot'].forEach(function(a){this.on('attr:'+a,this.refreshShoreline,this);},this);
    this.startLoadingWatch();
};
ToonWater.prototype.apply=function(){
    var live=new Set();
    this.entity.findComponents('render').forEach(function(r){
        r.meshInstances.forEach(function(mi){
            if(mi.skinInstance||mi.morphInstance)return;
            live.add(mi);
            var entry=this.original.find(function(e){return e.mi===mi;});
            if(entry){
                // A late material asset can overwrite our assignment after geometry arrives.
                if(mi.material!==this.material)entry.material=mi.material;
                mi.material=this.material; mi.castShadow=false; return;
            }
            entry={mi:mi,material:mi.material,mesh:mi.mesh,castShadow:mi.castShadow};
            // Built-in planes have only two triangles. Supply a modest wave grid automatically.
            if(r.type==='plane'){
                if(!this.plane){
                    this.plane=pc.Mesh.fromGeometry(this.app.graphicsDevice,new pc.PlaneGeometry({halfExtents:new pc.Vec2(0.5,0.5),widthSegments:64,lengthSegments:64}));
                    this.generated.push(this.plane);
                }
                mi.mesh=this.plane;
            }
            this.original.push(entry); mi.material=this.material; mi.castShadow=false;
        },this);
    },this);
    this.original=this.original.filter(function(e){
        if(live.has(e.mi))return true;
        if(e.mi.mesh && e.mi.material===this.material){e.mi.material=e.material;e.mi.mesh=e.mesh;e.mi.castShadow=e.castShadow;}
        return false;
    },this);
    if(!this.shoreTexture)this.emptyShoreline();
    this.queueShoreline(); this.parameters();
};
// Loading work is event-driven. No polling or loading logic is added to update().
ToonWater.prototype.emptyShoreline=function(){
    this.shoreTexture=new pc.Texture(this.app.graphicsDevice,{name:'Water loading fallback',width:1,height:1,format:pc.PIXELFORMAT_R8,mipmaps:false,minFilter:pc.FILTER_LINEAR,magFilter:pc.FILTER_LINEAR});
    this.shoreTexture.lock().set(new Uint8Array([255]));this.shoreTexture.unlock();
    this.material.setParameter('uShore',this.shoreTexture);
    this.material.setParameter('uMap',[0,0,1,1]);
    this.material.setParameter('uShoreRange',Math.max(0.1,this.shoreWidth)*5);
};
ToonWater.prototype.startLoadingWatch=function(){
    if(this.shoreLocked){this.apply();return;}
    if(this.watching)return;
    this.watching=true;this.renderWatches=new Map();this.failedAssets=new Set();
    this.app.assets.on('load',this.onAssetReady,this);
    this.app.assets.on('error',this.onLoadError,this);
    this.app.systems.on('meshInstancesChange',this.queueLoadingSync,this);
    this.app.systems.render.on('add',this.queueLoadingSync,this);
    this.app.systems.render.on('remove',this.queueLoadingSync,this);
    this.syncLoading();
};
ToonWater.prototype.stopLoadingWatch=function(){
    this.watching=false;
    clearTimeout(this.syncTimer);clearTimeout(this.shoreTimer);
    this.syncTimer=null;this.shoreTimer=null;
    this.app.assets.off('load',this.onAssetReady,this);
    this.app.assets.off('error',this.onLoadError,this);
    this.app.systems.off('meshInstancesChange',this.queueLoadingSync,this);
    this.app.systems.render.off('add',this.queueLoadingSync,this);
    this.app.systems.render.off('remove',this.queueLoadingSync,this);
    if(this.renderWatches)this.renderWatches.forEach(function(r){
        r.entity.off('inserthierarchy',this.queueLoadingSync,this);
        r.entity.off('removehierarchy',this.queueLoadingSync,this);
        r.off('set_enabled',this.queueLoadingSync,this);
    },this);
    if(this.renderWatches)this.renderWatches.clear();
    if(this.failedAssets)this.failedAssets.clear();
};
ToonWater.prototype.onAssetReady=function(asset){
    if(['render','container','model','material'].indexOf(asset.type)!==-1)this.queueLoadingSync();
};
ToonWater.prototype.onLoadError=function(error,asset){if(asset&&this.failedAssets)this.failedAssets.add(asset);this.queueLoadingSync();};
ToonWater.prototype.queueLoadingSync=function(){
    if(!this.watching||this.syncTimer!=null)return;
    // Let PlayCanvas finish constructing meshes and assigning source materials first.
    this.syncTimer=setTimeout(function(){this.syncTimer=null;if(this.watching)this.syncLoading();}.bind(this),0);
};
ToonWater.prototype.syncLoading=function(){
    var renders=this.shoreRenders(),present=new Set(renders);
    this.entity.findComponents('render').forEach(function(r){if(!present.has(r)){renders.push(r);present.add(r);}});
    this.renderWatches.forEach(function(r){
        if(!present.has(r)){
            r.entity.off('inserthierarchy',this.queueLoadingSync,this);
            r.entity.off('removehierarchy',this.queueLoadingSync,this);
            r.off('set_enabled',this.queueLoadingSync,this);
            this.renderWatches.delete(r);
        }
    },this);
    renders.forEach(function(r){
        if(this.renderWatches.has(r))return;
        this.renderWatches.set(r,r);
        r.entity.on('inserthierarchy',this.queueLoadingSync,this);
        r.entity.on('removehierarchy',this.queueLoadingSync,this);
        r.on('set_enabled',this.queueLoadingSync,this);
    },this);
    this.apply();
};
ToonWater.prototype.queueShoreline=function(){
    if(!this.watching||this.shoreLocked)return;
    clearTimeout(this.shoreTimer);
    // One startup quiet window. After baking, remove every loading listener.
    this.shoreTimer=setTimeout(function(){
        this.shoreTimer=null;
        if(!this.watching)return;
        var pending=false,waterRenders=this.entity.findComponents('render');
        this.renderWatches.forEach(function(r){
            var asset=this.app.assets.get(r.asset);
            if(r.enabled&&r.entity.enabled&&asset&&!this.failedAssets.has(asset)&&(asset.loading||asset.loaded===false))pending=true;
            // Wait for source materials too, so they cannot overwrite water after locking.
            if(waterRenders.indexOf(r)!==-1){
                (r.materialAssets||[]).forEach(function(id){
                    var a=this.app.assets.get(id);
                    if(a&&!this.failedAssets.has(a)&&(a.loading||a.loaded===false))pending=true;
                },this);
            }
        },this);
        // Completion/error events schedule the next attempt; never spin a polling timer.
        if(!pending&&this.original.length){
            this.rebuildShoreline();
            this.shoreLocked=true;
            this.stopLoadingWatch();
        }
    }.bind(this),1000);
};
// Explicit opt-in for a new level or deliberate changes to static terrain.
ToonWater.prototype.refreshShoreline=function(){
    this.shoreLocked=false;
    if(this.enabled!==false)this.startLoadingWatch();
    this.queueShoreline();
};
ToonWater.prototype.shoreRenders=function(){
    if(this.shoreFoam===false)return [];
    return (this.shoreRoot||this.app.root).findComponents('render').filter(function(r){
        for(var e=r.entity;e;e=e.parent){
            if((e.tags&&e.tags.has('water-ignore'))||e.anim||e.animation||
                (e.rigidbody&&e.rigidbody.type!=='static'))return false;
        }
        return true;
    });
};
ToonWater.prototype.restore=function(){
    this.original.forEach(function(e){if(e.mi.mesh && e.mi.material===this.material){e.mi.material=e.material;e.mi.mesh=e.mesh;e.mi.castShadow=e.castShadow;}},this);
    this.original.length=0;
};
ToonWater.prototype.parameters=function(){
    if(!this.material)return;
    this.material.setParameter('uWater',[this.waterColor.r,this.waterColor.g,this.waterColor.b]);
    this.material.setParameter('uShallow',[this.shallowColor.r,this.shallowColor.g,this.shallowColor.b]);
    this.material.setParameter('uFoam',[this.highlightColor.r,this.highlightColor.g,this.highlightColor.b]);
    this.material.setParameter('uFrequency',Math.PI*2/Math.max(0.1,this.tileSize));
    this.material.setParameter('uHeight',Math.max(0,this.waveHeight));
    this.material.setParameter('uWidth',Math.max(0.1,this.shoreWidth));
    this.material.setParameter('uTime',this.time);
};
ToonWater.prototype.update=function(dt){
    this.time=(this.time+dt*Math.max(0,this.flowSpeed))%(Math.PI*2*1024);
    if(this.flowSpeed>0)this.material.setParameter('uTime',this.time);
};

// Find horizontal water/terrain intersections once, rasterize, then two-pass distance transform.
// No physics, depth grab, render target, per-frame terrain scan, or imported mask is required.
ToonWater.prototype.rebuildShoreline=function(){
    if(!this.original.length)return;
    var start=performance.now(), n=this.shoreFoam?this.shoreResolution:1;
    n=n===128||n===256||n===512?n:1;
    var bounds=this.original[0].mi.aabb.clone();
    this.original.forEach(function(e){bounds.add(e.mi.aabb);});
    var min=bounds.getMin(),max=bounds.getMax(),sx=Math.max(0.1,max.x-min.x),sz=Math.max(0.1,max.z-min.z);
    var level=bounds.center.y,range=Math.max(0.1,this.shoreWidth)*5;
    var dist=new Float32Array(n*n);dist.fill(range);
    var dx=sx/n,dz=sz/n,diag=Math.sqrt(dx*dx+dz*dz),segments=0,triangles=0;
    var water=new Set(this.original.map(function(e){return e.mi;}));
    function line(a,b){
        var x0=(a.x-min.x)/sx*n,z0=(a.z-min.z)/sz*n,x1=(b.x-min.x)/sx*n,z1=(b.z-min.z)/sz*n;
        var steps=Math.ceil(Math.max(Math.abs(x1-x0),Math.abs(z1-z0))*2);
        for(var k=0;k<=steps;k++){
            var t=steps?k/steps:0,x=Math.floor(x0+(x1-x0)*t),z=Math.floor(z0+(z1-z0)*t);
            if(x>=0&&z>=0&&x<n&&z<n)dist[z*n+x]=0;
        }
        segments++;
    }
    if(this.shoreFoam)this.shoreRenders().forEach(function(r){
        if(!r.enabled||!r.entity.enabled)return;
        r.meshInstances.forEach(function(mi){
            if(water.has(mi)||mi.skinInstance||mi.morphInstance||!mi.visible)return;
            var bb=mi.aabb,lo=bb.getMin(),hi=bb.getMax();
            if(lo.y>level||hi.y<level||hi.x<min.x||lo.x>max.x||hi.z<min.z||lo.z>max.z)return;
            var pos=[],indices=[];mi.mesh.getPositions(pos);mi.mesh.getIndices(indices);
            if(!indices.length)for(var k=0;k<pos.length/3;k++)indices.push(k);
            var matrix=mi.node.getWorldTransform(),points=[];
            for(var i=0;i<pos.length;i+=3){var v=new pc.Vec3(pos[i],pos[i+1],pos[i+2]);matrix.transformPoint(v,v);points.push(v);}
            for(var j=0;j+2<indices.length;j+=3){
                triangles++;
                var verts=[points[indices[j]],points[indices[j+1]],points[indices[j+2]]],hits=[];
                for(var e=0;e<3;e++){
                    var a=verts[e],b=verts[(e+1)%3],da=a.y-level,db=b.y-level;
                    if((da<=0&&db>0)||(db<=0&&da>0)){
                        var t=da/(da-db);hits.push({x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t});
                    }
                }
                if(hits.length===2)line(hits[0],hits[1]);
            }
        });
    });
    for(var y=0;y<n;y++)for(var x=0;x<n;x++){
        var p=y*n+x,d=dist[p];
        if(x>0)d=Math.min(d,dist[p-1]+dx);
        if(y>0){d=Math.min(d,dist[p-n]+dz);if(x>0)d=Math.min(d,dist[p-n-1]+diag);if(x<n-1)d=Math.min(d,dist[p-n+1]+diag);}
        dist[p]=d;
    }
    for(var y=n-1;y>=0;y--)for(var x=n-1;x>=0;x--){
        var p=y*n+x,d=dist[p];
        if(x<n-1)d=Math.min(d,dist[p+1]+dx);
        if(y<n-1){d=Math.min(d,dist[p+n]+dz);if(x>0)d=Math.min(d,dist[p+n-1]+diag);if(x<n-1)d=Math.min(d,dist[p+n+1]+diag);}
        dist[p]=d;
    }
    var bytes=new Uint8Array(n*n);
    for(var p=0;p<n*n;p++){bytes[p]=Math.round(Math.min(1,dist[p]/range)*255);}
    if(this.shoreTexture)this.shoreTexture.destroy();
    this.shoreTexture=new pc.Texture(this.app.graphicsDevice,{name:'Automatic water shoreline',width:n,height:n,format:pc.PIXELFORMAT_R8,mipmaps:false,minFilter:pc.FILTER_LINEAR,magFilter:pc.FILTER_LINEAR,addressU:pc.ADDRESS_CLAMP_TO_EDGE,addressV:pc.ADDRESS_CLAMP_TO_EDGE});
    this.shoreTexture.lock().set(bytes);this.shoreTexture.unlock();
    this.material.setParameter('uShore',this.shoreTexture);
    this.material.setParameter('uMap',[min.x,min.z,1/sx,1/sz]);
    this.material.setParameter('uShoreRange',range);
    this.parameters();
    console.info('toonWater: shoreline '+segments+' segments, '+triangles+' triangles, '+n+'px, '+(performance.now()-start).toFixed(1)+'ms startup bake.');
};


